        minute = 0;
        second = 0.0;
    }else if( sqlite3_stricmp(zPrecision, "minute")==0 ){
        second = 0.0;
    }else if( sqlite3_stricmp(zPrecision, "second")==0 ){
        /* No truncation needed */
    }else{
        sqlite3_result_error(context, "Invalid precision for date_trunc()", -1);
        return;
