    for(i=0; i<2 && isdigit(zDate[i]); i++) {
        *day = *day*10 + (zDate[i] - '0');
    }
    if( i==0 ) return 1;
    zDate += i;

    /* Check if there's more (time portion) */
    if( *zDate && (isdigit(*zDate) || *zDate==':' || *zDate=='.') ) {
        /* Skip separator */
        while( *zDate && !isdigit(*zDate) ) zDate++;

        /* Parse hour (1-2 digits) */
        for(i=0; i<2 && isdigit(zDate[i]); i++) {
