        }
        if( i==0 ) return 1;
        zDate += i;

        /* Parse seconds (may have decimal part) */
        if( *zDate && (*zDate=='.' || isdigit(*zDate)) ) {
            if( *zDate=='.' ) {
                zDate++;
                *second = 0.0;
